package com.landwatch.geospatial;

import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Encapsulates the quantitative metrics, binary mask, and visual maps
 * generated by the baseline change-detection pipeline.
 */
public class ChangeDetectionResult {

    private final int width;
    private final int height;
    private final long totalPixels;
    private final long rawChangedPixels;
    private final long filteredChangedPixels;
    private final long unchangedPixels;
    private final double changePercentage;
    private final int numConnectedRegions;
    private final int otsuThreshold;
    private final long executionTimeMs;

    private final boolean[][] binaryMask;
    private final double[][] differenceMatrix;
    private final List<Rectangle> boundingBoxes;

    private BufferedImage binaryChangeMap;
    private BufferedImage overlayChangeMap;

    public ChangeDetectionResult(int width, int height,
                                 long rawChangedPixels,
                                 long filteredChangedPixels,
                                 int numConnectedRegions,
                                 int otsuThreshold,
                                 long executionTimeMs,
                                 boolean[][] binaryMask,
                                 double[][] differenceMatrix,
                                 List<Rectangle> boundingBoxes) {
        this.width = width;
        this.height = height;
        this.totalPixels = (long) width * height;
        this.rawChangedPixels = rawChangedPixels;
        this.filteredChangedPixels = filteredChangedPixels;
        this.unchangedPixels = totalPixels - filteredChangedPixels;
        this.changePercentage = (totalPixels > 0) ? (filteredChangedPixels * 100.0 / totalPixels) : 0.0;
        this.numConnectedRegions = numConnectedRegions;
        this.otsuThreshold = otsuThreshold;
        this.executionTimeMs = executionTimeMs;
        this.binaryMask = binaryMask;
        this.differenceMatrix = differenceMatrix;
        this.boundingBoxes = (boundingBoxes != null) ? new ArrayList<>(boundingBoxes) : Collections.emptyList();
    }

    public int getWidth() { return width; }
    public int getHeight() { return height; }
    public long getTotalPixels() { return totalPixels; }
    public long getRawChangedPixels() { return rawChangedPixels; }
    public long getFilteredChangedPixels() { return filteredChangedPixels; }
    public long getUnchangedPixels() { return unchangedPixels; }
    public double getChangePercentage() { return changePercentage; }
    public int getNumConnectedRegions() { return numConnectedRegions; }
    public int getOtsuThreshold() { return otsuThreshold; }
    public long getExecutionTimeMs() { return executionTimeMs; }
    public boolean[][] getBinaryMask() { return binaryMask; }
    public double[][] getDifferenceMatrix() { return differenceMatrix; }
    public List<Rectangle> getBoundingBoxes() { return Collections.unmodifiableList(boundingBoxes); }

    public BufferedImage getBinaryChangeMap() { return binaryChangeMap; }
    public void setBinaryChangeMap(BufferedImage binaryChangeMap) { this.binaryChangeMap = binaryChangeMap; }

    public BufferedImage getOverlayChangeMap() { return overlayChangeMap; }
    public void setOverlayChangeMap(BufferedImage overlayChangeMap) { this.overlayChangeMap = overlayChangeMap; }

    /**
     * Determines the encroachment risk level based on actual altered percentage.
     */
    public String getRiskCategory() {
        if (filteredChangedPixels == 0) {
            return "NO CHANGE";
        } else if (changePercentage < 1.0) {
            return "LOW / LOCALIZED";
        } else if (changePercentage < 5.0) {
            return "MODERATE RISK";
        } else if (changePercentage < 15.0) {
            return "HIGH ENCROACHMENT";
        } else {
            return "CRITICAL / SEVERE";
        }
    }

    /**
     * Formatted string summary for logs and reports.
     */
    public String getSummary() {
        return String.format(
                "Change Detection Summary:\n" +
                "  • Dimensions: %d x %d (%d total pixels)\n" +
                "  • Raw Changed Pixels: %,d\n" +
                "  • Filtered Changed Pixels: %,d (%.2f%%)\n" +
                "  • Unchanged Pixels: %,d\n" +
                "  • Connected Encroachment Clusters: %d\n" +
                "  • Otsu Adaptive Threshold: %d / 255\n" +
                "  • Risk Category: %s\n" +
                "  • Latency: %d ms",
                width, height, totalPixels,
                rawChangedPixels,
                filteredChangedPixels, changePercentage,
                unchangedPixels,
                numConnectedRegions,
                otsuThreshold,
                getRiskCategory(),
                executionTimeMs);
    }
}
